def norm(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return tuple(sorted((r-min(rs),c-min(cs)) for r,c in cells))

def rots(cells):
    out=set()
    cur=norm(cells)
    for _ in range(4):
        out.add(cur)
        cur=norm([(c,-r) for r,c in cur])
    # reflections too optionally
    out.add(norm([(r,-c) for r,c in norm(cells)]))
    out.add(norm([(-r,c) for r,c in norm(cells)]))
    return out

def bbox(cells):
    rs=[r for r,c in cells]; cs=[c for r,c in cells]
    return min(rs),min(cs),max(rs),max(cs)

